I inlined the profile field lookup so the constructor scans the already-resolved message’s field table instead of calling `GetFieldIndex` (which performs a second `GetMesg` lookup and a function call). This preserves the first-match semantics and invalid index handling.

```cpp
Field::Field(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
    : FieldBase()
    , profile(Profile::GetMesg(mesgNum))
    , profileIndex(FIT_UINT8_INVALID)
    , type(FIT_UINT8_INVALID)
    , isFieldExpanded(FIT_FALSE)
{
    if (profile != nullptr)
    {
        for (FIT_UINT8 i = 0; i < profile->numFields; ++i)
        {
            if (profile->fields[i].num == fieldNum)
            {
                profileIndex = i;
                break;
            }
        }
    }
}
```

